draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  for (let i = 0; i < 10; i++) {
    ctx.moveTo(50 + i * 50, H / 2 + Math.sin(t + i) * 20);
    ctx.lineTo(50 + i * 50, H / 2 + Math.sin(t + i) * 20 + 50);
  }
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 20 + Math.sin(t) * 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.restore();
}
